import {MAPS,challengePassed,enemyKey,ENEMIES,BY_ID} from './data.js';
export const SAVE_KEY='temple-guardians-battle-v5',PROGRESS_KEY='temple-guardians-journey-v2';
export function emptyJourney(){return {temples:{},seen:[],stories:[],festival:[],version:2};}
export function migrateJourney(old){const j=emptyJourney();const ids=['banyan','lotus','mountain'];for(const [i,shield] of Object.entries(old||{})){if(ids[i]&&Number.isFinite(shield)&&shield>0)j.temples[ids[i]]={shield,lamps:[true,shield>=20,false]};}return j;}
export function recordVictory(journey,battle){if(battle.status!=='won'||battle.mode==='survival')return null;journey.encounters??={};const key=battle.map.id+':'+battle.encounter;journey.encounters[key]=true;journey.difficulties??={};journey.difficulties[battle.difficulty]??={};journey.difficulties[battle.difficulty][key]=[true,battle.damageTaken===0,challengePassed(battle)];if(battle.encounter<2)return {encounterOnly:true,lamps:[false,false,false]};let id=battle.map.id,old=journey.temples[id],earned=[true,battle.damageTaken===0,challengePassed(battle)];const lamps=earned.map((v,i)=>v||!!old?.lamps?.[i]);const newlyLit=earned.map((v,i)=>v&&!old?.lamps?.[i]);journey.temples[id]={shield:Math.max(old?.shield||0,battle.shield),lamps};return {earned,newlyLit,lamps,festivalUnlocked:lamps.every(Boolean)&&!old?.lamps?.every(Boolean)};}
export function introductions(specs,mapIndex,seen=[]){const found=new Set(seen),result=[];for(const spec of specs){let key=enemyKey(spec,mapIndex);if(found.has(key))continue;found.add(key);const base=ENEMIES[spec.type],map=MAPS[mapIndex];result.push({key,...base,...spec,atlas:spec.type==='boss'?map.bossAtlas:base.atlas,cell:spec.type==='boss'?map.bossCell:base.cell,family:spec.type==='boss'?(map.bossFamily??3):base.family,name:spec.type==='boss'?map.bossName:spec.name||base.name,quote:spec.type==='boss'?map.quote:base.quote,hint:spec.elite?({mirror:'Lightning creates veiled copies. Use Saraswati with fire or wind.',night:'Disappears periodically. Saraswati reveals the hidden commander.',seals:'Cycles protection between Agni, Varuna and Indra. Use several damage sources.'}[spec.boon]):spec.type==='boss'?map.boon+' Do not let the commander reach the sanctuary.':base.hint,protectionText:spec.protection?`${BY_ID[spec.protection].name} will not damage or hinder this foe.`:''});}return result;}
export function challengeProgress(b){switch(b.map.challengeKind){case'four':return `${b.usedDeities.length} deity types used · maximum 4`;case'early':return `${b.earlyCalls} / 2 waves called early`;case'exalted':return `${b.shrines.filter(s=>s.level===3).length} / 3 Exalted shrines`;case'patient':return `${b.interventions} interventions used · aim for 0`;case'seven':return `${b.usedDeities.length} / 7 deity types established`;default:return '';}}
